const body = $input.first().json.body || {};
const text = String(body.text || '').slice(0, 2000);
if (!text.trim()) { throw new Error('text is required'); }
return [{ json: { text, user: String(body.user || 'аноним') } }];

const r = $input.first().json;
let parsed;
try { parsed = JSON.parse(r.choices[0].message.content); } catch (e) { parsed = { category: 'прочее', priority: 'средний', summary: 'не удалось разобрать ответ модели', is_request: true, needs_clarification: false, clarify_question: '' }; }
parsed.needs_clarification = parsed.needs_clarification === true;
parsed.clarify_question = String(parsed.clarify_question || '');
return [{ json: { ok: true, ...parsed } }];

// Лид-захват: каждая классифицированная заявка попадает в очередь менеджера
const staticData = $getWorkflowStaticData('global');
staticData.leads = staticData.leads || [];
if ($json.is_request === false || $json.needs_clarification === true) { return [{ json: { ...$json, lead_saved: false } }]; }
const src = $('Валидация').first().json;
staticData.leads.push({
  user: src.user, text: String(src.text || '').slice(0, 200),
  source_msg: String(src.text || '').slice(0, 1000),
  category: $json.category, priority: $json.priority, summary: $json.summary,
  date: null,
  ts: new Date().toISOString(),
});
if (staticData.leads.length > 200) { staticData.leads.splice(0, staticData.leads.length - 200); }
return [{ json: { ...$json, lead_saved: true } }];

// Очередь заявок. Приватность: при leads_private=true пользователь видит только свои лиды
const cfg = $('Настройки демо').first().json;
const staticData = $getWorkflowStaticData('global');
staticData.leads = staticData.leads || [];
const user = (($('Webhook leads').first().json.body) || {}).user || '';
let leads = staticData.leads;
if (cfg.leads_private) { leads = leads.filter(l => l.user && l.user === user); }
const max = cfg.leads_max || 20;
return [{ json: { ok: true, leads_private: !!cfg.leads_private, total: leads.length, leads: leads.slice(-max).reverse() } }];

const staticData = $getWorkflowStaticData('global');
staticData.leads = staticData.leads || [];
const body = $input.first().json.body || {};
const user = String(body.user || '');
const date = String(body.date || '');
if (!user || !date) { return [{ json: { ok: false, error: 'user and date required' } }]; }
for (let i = staticData.leads.length - 1; i >= 0; i--) {
  const l = staticData.leads[i];
  if (l.user === user && !l.date) { l.date = date; return [{ json: { ok: true, lead: l } }]; }
}
return [{ json: { ok: false, error: 'нет открытой заявки' } }];
